//! The generated C# runtime support types, emitted once per run in the root
//! namespace: `Violation`, `SpecJson`, `ValueEquality`, and — only when a model
//! materializes them — `TemporalSupport` and `Base64Support`.

use std::path::PathBuf;

use crate::json_schema::content_encoding::Encoding;
use crate::json_schema::format::TemporalKind;

use super::schema::dotnet_pattern;
use super::{GENERATED_CODE_ATTRIBUTE, cs_string};

const HEADER: &str = concat!(
    "// <auto-generated />\n// Generated by nexgen v",
    env!("CARGO_PKG_VERSION"),
    ". DO NOT EDIT!\n#nullable enable\n\n"
);

pub(super) fn files(
    namespace: &str,
    temporal: bool,
    content_encoding: bool,
) -> Vec<(PathBuf, String)> {
    let mut files = vec![
        (
            PathBuf::from("Violation.cs"),
            wrap(
                namespace,
                &VIOLATION.replace("{generated}", GENERATED_CODE_ATTRIBUTE),
            ),
        ),
        (
            PathBuf::from("SpecJson.cs"),
            wrap(
                namespace,
                &SPEC_JSON.replace("{generated}", GENERATED_CODE_ATTRIBUTE),
            ),
        ),
        (
            PathBuf::from("ValueEquality.cs"),
            wrap(
                namespace,
                &VALUE_EQUALITY.replace("{generated}", GENERATED_CODE_ATTRIBUTE),
            ),
        ),
    ];
    if temporal {
        let body = TEMPORAL_SUPPORT
            .replace("{generated}", GENERATED_CODE_ATTRIBUTE)
            .replace(
                "{date_time}",
                &cs_string(&dotnet_pattern(TemporalKind::DateTime.pattern())),
            )
            .replace(
                "{date}",
                &cs_string(&dotnet_pattern(TemporalKind::Date.pattern())),
            )
            .replace(
                "{time}",
                &cs_string(&dotnet_pattern(TemporalKind::Time.pattern())),
            )
            .replace(
                "{duration}",
                &cs_string(&dotnet_pattern(TemporalKind::Duration.pattern())),
            );
        files.push((PathBuf::from("TemporalSupport.cs"), wrap(namespace, &body)));
    }
    if content_encoding {
        let body = BASE64_SUPPORT
            .replace("{generated}", GENERATED_CODE_ATTRIBUTE)
            .replace(
                "{base64}",
                &cs_string(&dotnet_pattern(Encoding::Base64.pattern())),
            )
            .replace(
                "{base64url}",
                &cs_string(&dotnet_pattern(Encoding::Base64Url.pattern())),
            );
        files.push((PathBuf::from("Base64Support.cs"), wrap(namespace, &body)));
    }
    files
}

fn wrap(namespace: &str, body: &str) -> String {
    let mut output = String::from(HEADER);
    output.push_str(&format!("namespace {namespace}\n{{\n"));
    for line in body.trim_matches('\n').lines() {
        if line.is_empty() {
            output.push('\n');
        } else {
            output.push_str("    ");
            output.push_str(line);
            output.push('\n');
        }
    }
    output.push_str("}\n");
    output
}

const VIOLATION: &str = r#"
/// <summary>
/// A single constraint failure: the path of the offending value and a
/// human-readable reason.
/// </summary>
{generated}
public sealed record Violation(string Path, string Reason)
{
    /// <summary>
    /// The path of the member <paramref name="key"/> under <paramref name="parent"/>.
    /// </summary>
    internal static string Member(string parent, string key) => Join(parent, Segment(key));

    /// <summary>
    /// Appends an already-encoded member segment to <paramref name="parent"/>.
    /// </summary>
    internal static string Join(string parent, string segment)
    {
        if (parent.Length == 0)
        {
            return segment;
        }
        return segment.StartsWith('[') ? parent + segment : parent + "." + segment;
    }

    /// <summary>
    /// The path of the array element <paramref name="index"/> under <paramref name="parent"/>.
    /// </summary>
    internal static string Index(string parent, int index) =>
        parent + "[" + index.ToString(global::System.Globalization.CultureInfo.InvariantCulture) + "]";

    /// <summary>
    /// Encodes one member key: identifier-like keys as-is, every other key
    /// bracket-quoted so dots, brackets, quotes and backslashes stay unambiguous.
    /// </summary>
    internal static string Segment(string key)
    {
        if (IsIdentifier(key))
        {
            return key;
        }
        return "[\"" + key.Replace("\\", "\\\\").Replace("\"", "\\\"") + "\"]";
    }

    private static bool IsIdentifier(string key)
    {
        if (key.Length == 0 || !(key[0] == '_' || char.IsAsciiLetter(key[0])))
        {
            return false;
        }
        foreach (var character in key)
        {
            if (!(character == '_' || char.IsAsciiLetterOrDigit(character)))
            {
                return false;
            }
        }
        return true;
    }

    /// <summary>
    /// The non-retryable <c>PayloadValidationError</c> application failure
    /// carrying <paramref name="violations"/> as its first detail.
    /// </summary>
    internal static global::System.Exception Failure(global::System.Collections.Generic.IReadOnlyList<Violation> violations) =>
        global::Temporalio.Converters.PayloadValidationError.CreateException(violations);

    /// <inheritdoc/>
    public override string ToString() => Path.Length == 0 ? Reason : Path + ": " + Reason;
}
"#;

const SPEC_JSON: &str = r#"
/// <summary>
/// Shared JSON reading helpers enforcing the JSON Schema numeric semantics.
/// </summary>
{generated}
internal static class SpecJson
{
    /// <summary>
    /// The largest integer magnitude every target can carry exactly: 2^53 - 1.
    /// </summary>
    public const long IntegerCap = 9007199254740991L;

    /// <summary>
    /// An object's members by name. A repeated key keeps its last value, the
    /// same rule every target's decoder applies.
    /// </summary>
    public static global::System.Collections.Generic.Dictionary<string, global::System.Text.Json.JsonElement> Members(global::System.Text.Json.JsonElement node)
    {
        var members = new global::System.Collections.Generic.Dictionary<string, global::System.Text.Json.JsonElement>(global::System.StringComparer.Ordinal);
        foreach (var member in node.EnumerateObject())
        {
            members[member.Name] = member.Value;
        }
        return members;
    }

    /// <summary>
    /// Reads a JSON number as a spec integer. Integral spellings (<c>1.0</c>,
    /// <c>1e2</c>) are accepted, fractional values rejected, and magnitudes past
    /// 2^53 - 1 rejected. Classification uses the exact token, never a rounded
    /// <c>double</c>.
    /// </summary>
    public static long? SpecLong(global::System.Text.Json.JsonElement node, string path, global::System.Collections.Generic.List<Violation> violations)
    {
        if (node.ValueKind != global::System.Text.Json.JsonValueKind.Number)
        {
            violations.Add(new Violation(path, "expected integer"));
            return null;
        }
        switch (ClassifyInteger(node.GetRawText(), out var value))
        {
            case IntegerClass.Integer:
                return value;
            case IntegerClass.OverCap:
                violations.Add(new Violation(path, "exceeds ±(2^53-1) integer cap"));
                return null;
            default:
                violations.Add(new Violation(path, "not an integer"));
                return null;
        }
    }

    /// <summary>
    /// Whether a node is an accepted spec integer, without recording a violation.
    /// </summary>
    public static bool IsSpecLong(global::System.Text.Json.JsonElement node) =>
        node.ValueKind == global::System.Text.Json.JsonValueKind.Number
            && ClassifyInteger(node.GetRawText(), out _) == IntegerClass.Integer;

    /// <summary>
    /// Reads a JSON number as a finite binary64 value.
    /// </summary>
    public static double? SpecDouble(global::System.Text.Json.JsonElement node, string path, global::System.Collections.Generic.List<Violation> violations)
    {
        if (node.ValueKind != global::System.Text.Json.JsonValueKind.Number)
        {
            violations.Add(new Violation(path, "expected number"));
            return null;
        }
        var value = DoubleOf(node);
        if (!double.IsFinite(value))
        {
            violations.Add(new Violation(path, "must be a finite number, got " + node.GetRawText()));
            return null;
        }
        return value;
    }

    /// <summary>
    /// Whether a node is a JSON number with a finite binary64 value.
    /// </summary>
    public static bool IsFiniteNumber(global::System.Text.Json.JsonElement node) =>
        node.ValueKind == global::System.Text.Json.JsonValueKind.Number && double.IsFinite(DoubleOf(node));

    /// <summary>
    /// The nearest binary64 value of a JSON number token.
    /// </summary>
    public static double DoubleOf(global::System.Text.Json.JsonElement node) =>
        double.Parse(node.GetRawText(), global::System.Globalization.NumberStyles.Float, global::System.Globalization.CultureInfo.InvariantCulture);

    /// <summary>
    /// The number of Unicode code points in <paramref name="value"/> (an
    /// unpaired surrogate counts as one).
    /// </summary>
    public static int CodePoints(string value)
    {
        var count = value.Length;
        for (var index = 0; index + 1 < value.Length; index++)
        {
            if (char.IsHighSurrogate(value[index]) && char.IsLowSurrogate(value[index + 1]))
            {
                count--;
                index++;
            }
        }
        return count;
    }

    /// <summary>
    /// An in-memory <c>number</c> equality key, folding <c>-0.0</c> onto <c>0.0</c>.
    /// </summary>
    public static object? NumberKey(double? value) => value is { } number ? (number == 0.0 ? 0.0 : number) : null;

    /// <summary>
    /// A JSON-value equality key: numbers compare mathematically (signed zero
    /// folded), objects compare without regard to member order.
    /// </summary>
    public static string ValueKey(global::System.Text.Json.JsonElement node)
    {
        var builder = new global::System.Text.StringBuilder();
        AppendKey(builder, node);
        return builder.ToString();
    }

    private static void AppendKey(global::System.Text.StringBuilder builder, global::System.Text.Json.JsonElement node)
    {
        switch (node.ValueKind)
        {
            case global::System.Text.Json.JsonValueKind.Number:
                var number = DoubleOf(node);
                builder.Append('n').Append((number == 0.0 ? 0.0 : number).ToString("R", global::System.Globalization.CultureInfo.InvariantCulture)).Append(';');
                break;
            case global::System.Text.Json.JsonValueKind.String:
                var text = node.GetString()!;
                builder.Append('s').Append(text.Length).Append(':').Append(text);
                break;
            case global::System.Text.Json.JsonValueKind.True:
                builder.Append('t');
                break;
            case global::System.Text.Json.JsonValueKind.False:
                builder.Append('f');
                break;
            case global::System.Text.Json.JsonValueKind.Array:
                builder.Append('[');
                foreach (var element in node.EnumerateArray())
                {
                    AppendKey(builder, element);
                }
                builder.Append(']');
                break;
            case global::System.Text.Json.JsonValueKind.Object:
                builder.Append('{');
                var members = Members(node);
                var names = new global::System.Collections.Generic.List<string>(members.Keys);
                names.Sort(global::System.StringComparer.Ordinal);
                foreach (var name in names)
                {
                    builder.Append(name.Length).Append(':').Append(name);
                    AppendKey(builder, members[name]);
                }
                builder.Append('}');
                break;
            default:
                builder.Append('z');
                break;
        }
    }

    private enum IntegerClass
    {
        Integer,
        Fractional,
        OverCap,
    }

    /// <summary>
    /// Classifies a JSON number token exactly: its significant digits and
    /// decimal exponent decide integrality and magnitude without rounding.
    /// </summary>
    private static IntegerClass ClassifyInteger(string raw, out long value)
    {
        value = 0;
        var index = 0;
        var negative = false;
        if (index < raw.Length && raw[index] == '-')
        {
            negative = true;
            index++;
        }
        var digits = new global::System.Text.StringBuilder();
        long scale = 0;
        while (index < raw.Length && char.IsAsciiDigit(raw[index]))
        {
            digits.Append(raw[index++]);
        }
        if (index < raw.Length && raw[index] == '.')
        {
            index++;
            while (index < raw.Length && char.IsAsciiDigit(raw[index]))
            {
                digits.Append(raw[index++]);
                scale--;
            }
        }
        if (index < raw.Length && (raw[index] == 'e' || raw[index] == 'E'))
        {
            index++;
            var exponentNegative = false;
            if (index < raw.Length && (raw[index] == '+' || raw[index] == '-'))
            {
                exponentNegative = raw[index] == '-';
                index++;
            }
            long exponent = 0;
            while (index < raw.Length && char.IsAsciiDigit(raw[index]))
            {
                exponent = global::System.Math.Min(exponent * 10 + (raw[index++] - '0'), 1_000_000_000L);
            }
            scale += exponentNegative ? -exponent : exponent;
        }
        var significant = digits.ToString().TrimStart('0');
        if (significant.Length == 0)
        {
            return IntegerClass.Integer;
        }
        var trimmed = significant.TrimEnd('0');
        scale += significant.Length - trimmed.Length;
        if (scale < 0)
        {
            return IntegerClass.Fractional;
        }
        if (trimmed.Length + scale > 16)
        {
            return IntegerClass.OverCap;
        }
        var magnitude = long.Parse(trimmed, global::System.Globalization.CultureInfo.InvariantCulture);
        for (var power = 0; power < scale; power++)
        {
            magnitude *= 10;
        }
        if (magnitude > IntegerCap)
        {
            return IntegerClass.OverCap;
        }
        value = negative ? -magnitude : magnitude;
        return IntegerClass.Integer;
    }
}
"#;

const VALUE_EQUALITY: &str = r#"
/// <summary>
/// Structural equality for generated models: collections and byte arrays
/// compare by content, numbers mathematically (signed zero folded).
/// </summary>
{generated}
internal static class ValueEquality
{
    /// <summary>
    /// The dictionary key standing in for a null element.
    /// </summary>
    public static readonly object NullKey = new();

    /// <summary>
    /// An equality comparer applying <see cref="Equal"/> and <see cref="Hash"/>.
    /// </summary>
    public static readonly global::System.Collections.Generic.IEqualityComparer<object> Comparer = new DeepComparer();

    /// <summary>
    /// Structural equality of two member values.
    /// </summary>
    public static bool Equal(object? left, object? right)
    {
        if (ReferenceEquals(left, right))
        {
            return true;
        }
        if (left is null || right is null)
        {
            return false;
        }
        switch (left)
        {
            case double leftNumber when right is double rightNumber:
                return leftNumber == rightNumber || (double.IsNaN(leftNumber) && double.IsNaN(rightNumber));
            case string leftText:
                return right is string rightText && string.Equals(leftText, rightText, global::System.StringComparison.Ordinal);
            case byte[] leftBytes:
                return right is byte[] rightBytes && global::System.MemoryExtensions.SequenceEqual<byte>(leftBytes, rightBytes);
            case global::System.Text.Json.JsonElement leftJson:
                return right is global::System.Text.Json.JsonElement rightJson && SpecJson.ValueKey(leftJson) == SpecJson.ValueKey(rightJson);
            case global::System.Collections.IDictionary leftMap:
                if (right is not global::System.Collections.IDictionary rightMap || leftMap.Count != rightMap.Count)
                {
                    return false;
                }
                foreach (global::System.Collections.DictionaryEntry entry in leftMap)
                {
                    if (!rightMap.Contains(entry.Key) || !Equal(entry.Value, rightMap[entry.Key]))
                    {
                        return false;
                    }
                }
                return true;
            case global::System.Collections.IEnumerable leftItems when right is global::System.Collections.IEnumerable rightItems:
                var leftEnumerator = leftItems.GetEnumerator();
                var rightEnumerator = rightItems.GetEnumerator();
                while (true)
                {
                    var leftHas = leftEnumerator.MoveNext();
                    var rightHas = rightEnumerator.MoveNext();
                    if (leftHas != rightHas)
                    {
                        return false;
                    }
                    if (!leftHas)
                    {
                        return true;
                    }
                    if (!Equal(leftEnumerator.Current, rightEnumerator.Current))
                    {
                        return false;
                    }
                }
            default:
                return left.Equals(right);
        }
    }

    /// <summary>
    /// A hash code consistent with <see cref="Equal"/>.
    /// </summary>
    public static int Hash(object? value)
    {
        switch (value)
        {
            case null:
                return 0;
            case double number:
                return number == 0.0 ? 0 : number.GetHashCode();
            case string text:
                return global::System.StringComparer.Ordinal.GetHashCode(text);
            case byte[] bytes:
                var bytesHash = new global::System.HashCode();
                bytesHash.AddBytes(bytes);
                return bytesHash.ToHashCode();
            case global::System.Text.Json.JsonElement json:
                return global::System.StringComparer.Ordinal.GetHashCode(SpecJson.ValueKey(json));
            case global::System.Collections.IDictionary map:
                var mapHash = 0;
                foreach (global::System.Collections.DictionaryEntry entry in map)
                {
                    mapHash += global::System.HashCode.Combine(Hash(entry.Key), Hash(entry.Value));
                }
                return mapHash;
            case global::System.Collections.IEnumerable items:
                var itemsHash = new global::System.HashCode();
                foreach (var item in items)
                {
                    itemsHash.Add(Hash(item));
                }
                return itemsHash.ToHashCode();
            default:
                return value.GetHashCode();
        }
    }

    private sealed class DeepComparer : global::System.Collections.Generic.IEqualityComparer<object>
    {
        public new bool Equals(object? left, object? right) => Equal(left, right);

        public int GetHashCode(object value) => Hash(value);
    }
}
"#;

